import { useState, KeyboardEvent } from 'react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/shared/ui/dialog'
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/shared/ui/alert-dialog'
import { Button } from '@/shared/ui/button'
import { Input } from '@/shared/ui/input'
import { Badge } from '@/shared/ui/badge'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/shared/ui/select'
import { useToast } from '@/shared/hooks/use-toast'
import { Layers, Plus, Trash2, Loader2 } from 'lucide-react'
import { useSetores, type SetorComContagem } from '../model/useSetores'

export interface SetorManagerProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  onChanged?: () => void;
}

export function SetorManager({ open, onOpenChange, onChanged }: SetorManagerProps) {
  const { setores, isLoading, criarSetor, moverItens, excluirSetor } = useSetores()
  const { toast } = useToast()

  const [novoNome, setNovoNome] = useState('')
  const [criando, setCriando] = useState(false)

  const [movendo, setMovendo] = useState<Record<string, boolean>>({})

  const [setorParaExcluir, setSetorParaExcluir] = useState<SetorComContagem | null>(null)
  const [excluindo, setExcluindo] = useState(false)

  const handleCriarSetor = async () => {
    if (!novoNome.trim() || criando) return
    setCriando(true)
    const result = await criarSetor(novoNome.trim())
    if (result.ok) {
      toast({ title: 'Sucesso', description: `Setor "${novoNome.trim()}" criado.` })
      setNovoNome('')
      onChanged?.()
    } else {
      toast({ variant: 'destructive', title: 'Erro ao criar setor', description: result.error })
    }
    setCriando(false)
  }

  const handleInputKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handleCriarSetor()
    }
  }

  const handleMoverItens = async (de: string, para: string) => {
    if (!para) return
    setMovendo(prev => ({ ...prev, [de]: true }))
    const result = await moverItens(de, para)
    if (result.ok) {
      toast({ title: 'Sucesso', description: `${result.movidos} ${result.movidos === 1 ? 'item movido' : 'itens movidos'} de "${de}" para "${para}".` })
      onChanged?.()
    } else {
      toast({ variant: 'destructive', title: 'Erro ao mover itens', description: result.error })
    }
    setMovendo(prev => ({ ...prev, [de]: false }))
  }

  const handleConfirmarExclusao = async () => {
    if (!setorParaExcluir || excluindo) return
    setExcluindo(true)
    const result = await excluirSetor(setorParaExcluir.nome)
    if (result.ok) {
      toast({ title: 'Sucesso', description: `Setor "${setorParaExcluir.nome}" excluído.` })
      onChanged?.()
    } else {
      toast({ variant: 'destructive', title: 'Erro ao excluir setor', description: result.error })
    }
    setExcluindo(false)
    setSetorParaExcluir(null)
  }

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl sm:max-w-[550px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-[#2D362E] dark:text-[#E6DCCF]">
              <Layers className="h-6 w-6" />
              Gerenciar Setores
            </DialogTitle>
            <DialogDescription className="text-gray-600 dark:text-gray-400">
              Crie, mova itens e organize os setores dos produtos.
            </DialogDescription>
          </DialogHeader>

          <div className="flex w-full items-center space-x-2 pt-4">
            <Input
              type="text"
              placeholder="Nome do novo setor"
              className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
              value={novoNome}
              onChange={(e) => setNovoNome(e.target.value)}
              onKeyDown={handleInputKeyDown}
              disabled={criando}
            />
            <Button
              type="button"
              className="bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-10"
              onClick={handleCriarSetor}
              disabled={criando || !novoNome.trim()}
            >
              {criando ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
              <span className="ml-2 hidden sm:inline">Criar</span>
            </Button>
          </div>

          <div className="relative pt-4">
            {isLoading ? (
              <div className="flex justify-center items-center h-[55vh]">
                <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
              </div>
            ) : (
              <div className="max-h-[55vh] overflow-y-auto space-y-2 pr-2 -mr-4">
                {setores.map((setor) => (
                  <div key={setor.nome} className="bg-white/40 dark:bg-black/20 border border-[#57715B]/10 rounded-xl p-3 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                    <div className="flex items-center gap-3 flex-1">
                      <span className="font-semibold text-[#2D362E] dark:text-[#E6DCCF]">{setor.nome}</span>
                      <Badge className="bg-[#57715B]/10 text-[#57715B] rounded-full">
                        {setor.itensAtivos} {setor.itensAtivos === 1 ? 'item' : 'itens'}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 w-full sm:w-auto">
                      <Select
                        onValueChange={(value) => handleMoverItens(setor.nome, value)}
                        disabled={setor.itensAtivos === 0 || movendo[setor.nome]}
                      >
                        <SelectTrigger className="w-full sm:w-[180px] bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl">
                          {movendo[setor.nome] ? 
                            <div className="flex items-center gap-2">
                              <Loader2 className="h-4 w-4 animate-spin" /> <span>Movendo...</span>
                            </div>
                           : <SelectValue placeholder="Mover itens para..." />}
                        </SelectTrigger>
                        <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
                          {setores.filter(s => s.nome !== setor.nome).map(destino => (
                            <SelectItem key={destino.nome} value={destino.nome} className="focus:bg-[#57715B]/10 rounded-lg">
                              {destino.nome}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-9 w-9 rounded-xl text-red-500 hover:bg-red-500/10 hover:text-red-600"
                        onClick={() => setSetorParaExcluir(setor)}
                        disabled={setor.itensAtivos > 0}
                        title={setor.itensAtivos > 0 ? `Mova os ${setor.itensAtivos} itens antes de excluir` : 'Excluir setor'}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!setorParaExcluir} onOpenChange={(isOpen) => !isOpen && setSetorParaExcluir(null)}>
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-[#2D362E] dark:text-[#E6DCCF]">Excluir setor?</AlertDialogTitle>
            <AlertDialogDescription>
              O setor <span className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">{setorParaExcluir?.nome}</span> será removido permanentemente. Essa ação não pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel asChild>
              <Button variant="ghost" className="rounded-xl">Cancelar</Button>
            </AlertDialogCancel>
            <AlertDialogAction 
              className="bg-red-600 hover:bg-red-700 text-white rounded-xl"
              onClick={handleConfirmarExclusao}
              disabled={excluindo}
            >
              {excluindo && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
