const [newSetorName, setNewSetorName] = useState<string>('');
const [selectedSetorToDelete, setSelectedSetorToDelete] =
  useState<string>('');

const createSetor = async (nome: string) => {
  if (!nome) return;
  try {
    const { error } = await supabase
      .from('setores')
      .insert({ nome, ativo: true });
    if (error) throw error;
    toast({ title: 'Setor criado com sucesso' });
    fetchSetores();
  } catch (e) {
    toast({ title: 'Erro ao criar setor', variant: 'destructive' });
  }
};

const deleteSetor = async (nome: string) => {
  if (!nome) return;
  try {
    const { error } = await supabase
      .from('setores')
      .delete()
      .eq('nome', nome);
    if (error) throw error;
    toast({ title: 'Setor deletado com sucesso' });
    fetchSetores();
    setSelectedSetorToDelete('');
  } catch (e) {
    toast({ title: 'Erro ao deletar setor', variant: 'destructive' });
  }
};

